Author:     John Bieling <john@thunderbird.net>
AuthorDate: Fri Mar 6 16:52:21 2026 -0500
Commit:     John Bieling <john@thunderbird.net>
CommitDate: Fri Mar 6 16:52:21 2026 -0500

    Bug 2020584 - Guard against extension buttons messing up toolbars during customization. r=mkmelin


    There is an edge case, when an extension with a toolbar button is added/enabled or
    disabled/uninstalled, while the associated toolbar is being customized. The items
    in the toolbar are wrapped at that moment, but the `customizable-toolbar` custom
    element does not handle that case properly and messes up the toolbar.

    Attempts to fix this became complicated very quickly. The suggested (temporary?)
    fix here is to force close the customization dialog, when an extension (or any other
    consumer) is trying to manually add buttons.

    This patch also introduces a `removeButton()` method on the customizable toolbar,
    to remove a button by removing it from the toolbar and the palette. The palette
    entries had not been deleted before.

    Differential Revision: https://phabricator.services.mozilla.com/D286164

diff --git a/mail/base/content/customizeToolbar.js b/mail/base/content/customizeToolbar.js
index 2b92dab306c..981039b7de1 100644
--- a/mail/base/content/customizeToolbar.js
+++ b/mail/base/content/customizeToolbar.js
@@ -49,6 +49,17 @@ function InitWithToolbox(aToolbox) {
     elts[i].addEventListener("drop", onToolbarDrop, true);
   }

+  gToolbox.addEventListener(
+    "customizationending",
+    function () {
+      finishToolbarCustomization();
+      if (!gToolboxSheet) {
+        window.close();
+      }
+    },
+    { once: true }
+  );
+
   initDialog();
 }

@@ -133,6 +144,9 @@ function onUnload() {
 }

 function finishToolbarCustomization() {
+  if (!gToolbox.customizing) {
+    return;
+  }
   removeToolboxListeners();
   unwrapToolbarItems();
   persistCurrentSets();
diff --git a/mail/base/content/widgets/customizable-toolbar.js b/mail/base/content/widgets/customizable-toolbar.js
index c61fc260a74..ea575d69168 100644
--- a/mail/base/content/widgets/customizable-toolbar.js
+++ b/mail/base/content/widgets/customizable-toolbar.js
@@ -93,7 +93,12 @@
     }

     /**
-     * Sets the current set of items in the toolbar.
+     * Reorders toolbar buttons to match the provided set, moves missing buttons
+     * from the palette onto the toolbar, and removes any removable buttons not
+     * in the new set (returning them to the palette, or removing them if the
+     * palette does not exist). Entries in the new set that do not map to any
+     * existing button are silently ignored and will not appear in subsequent
+     * get currentSet calls.
      *
      * @param {string} val - Comma-separated list of IDs or "__empty".
      * @returns {string} Comma-separated list of IDs or "__empty".
@@ -103,6 +108,12 @@
         return;
       }

+      // If the customization dialog is open, force it to close first, since
+      // the DOM changes made by this setter would corrupt its state.
+      if (this.toolbox?.customizing) {
+        this.toolbox.dispatchEvent(new CustomEvent("customizationending"));
+      }
+
       // Build a cache of items in the toolbarpalette.
       const palette = this.toolbox ? this.toolbox.palette : null;
       const paletteChildren = palette ? palette.children : [];
@@ -189,6 +200,22 @@
       return currentSet.join(",") || "__empty";
     }

+    /**
+     * Removes a button with the given ID from the toolbar and the palette.
+     * If the customization dialog is open, it is force-closed first.
+     *
+     * @param {string} id - The ID of the button to remove.
+     */
+    removeButton(id) {
+      if (this.toolbox?.customizing) {
+        this.toolbox.dispatchEvent(new CustomEvent("customizationending"));
+      }
+
+      document.getElementById(id)?.remove();
+
+      this.toolbox?.palette?.querySelector(`#${id}`)?.remove();
+    }
+
     /**
      * Return the ID for a given toolbar item node, with special handling for
      * some cases.
diff --git a/mail/components/extensions/ExtensionToolbarButtons.sys.mjs b/mail/components/extensions/ExtensionToolbarButtons.sys.mjs
index fef2944840a..768c344cef8 100644
--- a/mail/components/extensions/ExtensionToolbarButtons.sys.mjs
+++ b/mail/components/extensions/ExtensionToolbarButtons.sys.mjs
@@ -276,7 +276,8 @@ export class ToolbarButtonAPI extends ExtensionAPIPersistent {
     }

     // Get all toolbars which link to or are children of this.toolboxId and check
-    // if the button has been moved to a non-default toolbar.
+    // if the button has been moved to the XUL store currentset of a non-default
+    // toolbar.
     const toolbars = window.document.querySelectorAll(
       `#${this.toolboxId} toolbar, toolbar[toolboxid="${this.toolboxId}"]`
     );
@@ -293,11 +294,7 @@ export class ToolbarButtonAPI extends ExtensionAPIPersistent {

     const toolbar = document.getElementById(this.toolbarId);
     const button = this.makeButton(window);
-    if (toolbox.palette) {
-      toolbox.palette.appendChild(button);
-    } else {
-      toolbar.appendChild(button);
-    }
+    toolbox.palette.appendChild(button);

     // Handle the special case where this toolbar does not yet have a currentset
     // defined.
@@ -314,8 +311,12 @@ export class ToolbarButtonAPI extends ExtensionAPIPersistent {
       );
     }

-    // Add new buttons to currentset: If the extensionset does not include the
-    // button, it is a new one which needs to be added.
+    // Add new buttons to the XUL store currentset: If the extensionset does not
+    // include the button, it is a new one which needs to be added.
+    // Note: Customizing a toolbar, where we keep track of an extension button
+    //       in the XUL store, which is disabled (no button!), the customization
+    //       dialog will remove that info from the XUL store. Since it is still
+    //       in the extensionset, it will not be added on enable.
     const extensionSet = Services.xulStore
       .getValue(windowURL, this.toolbarId, "extensionset")
       .split(",")
@@ -429,9 +430,14 @@ export class ToolbarButtonAPI extends ExtensionAPIPersistent {
       document.removeEventListener("popupshowing", this);
     }

-    const button = document.getElementById(this.id);
-    if (button) {
-      button.remove();
+    const toolbar = document.getElementById(this.toolbarId);
+    if (toolbar.hasAttribute("customizable")) {
+      toolbar.removeButton(this.id);
+    } else {
+      const button = document.getElementById(this.id);
+      if (button) {
+        button.remove();
+      }
     }
   }
